import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), a = sc.nextInt(), b = sc.nextInt();
        // while (s++ < n) runs the body with s = 1..n; "s < a && s < b" means s < min(a, b).
        int s = 0, cut = Math.min(a, b);
        StringBuilder sb = new StringBuilder();
        while (s++ < n) {
            if (s < cut) continue;
            if (sb.length() > 0) sb.append(' ');
            sb.append(s);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	var n, a, b int
	fmt.Scan(&n, &a, &b)
	// while (s++ < n) runs the body with s = 1..n; "s < a && s < b" means s < min(a, b).
	cut := min(a, b)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	first := true
	for s := 1; s <= n; s++ {
		if s < cut {
			continue
		}
		if !first {
			w.WriteByte(' ')
		}
		first = false
		w.WriteString(strconv.Itoa(s))
	}
	w.WriteByte('\n')
}
